// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;
    function setUp() public { c = new Synth(address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(address actor, address spender, uint256 amount) public {
        vm.assume(actor != address(0) && spender != address(0));

        vm.prank(actor);
        c.approve(spender, amount);

        assertTrue(c.allowance(actor, spender) == amount);
    }
}

